def terminal_cell_width(text: str) -> int:
    plain = re.sub(r"</?color[^>]*>", "", text)
    width = 0
    for character in plain:
        if unicodedata.combining(character):
            continue
        width += 2 if unicodedata.east_asian_width(character) in {"W", "F"} else 1
    return width


